import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十五卦 無妄 天雷無妄 乾上震下","description":"周易 - 第二十五卦 無妄 天雷無妄 乾上震下","frontmatter":{"title":"第二十五卦 無妄 天雷無妄 乾上震下","description":"周易 - 第二十五卦 無妄 天雷無妄 乾上震下"},"headers":[],"relativePath":"classics/zhouyi/026.md","filePath":"classics/zhouyi/026.md"}'),l={name:"classics/zhouyi/026.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="無妄" tabindex="-1">無妄 <a class="header-anchor" href="#無妄" aria-label="Permalink to “無妄”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元，亨，利，貞。其匪正有眚，不利有攸往。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>無妄，剛自外來，而為主於內。動而健，剛中而應，大亨以正，天之命也。其匪正有眚，不利有攸往。無妄之往，何之矣？天命不佑，行矣哉？</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>天下雷行，物與無妄；先王以茂對時，育萬物。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>無妄，往吉。象曰：無妄 之往，得志也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>不耕穫，不菑畲，則利有攸往。象曰：不耕穫，未富也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>無妄之災，或繫之牛，行人之得，邑人之災。象曰：行人得牛，邑人災也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>可貞，無咎。象曰：可貞無咎，固有之也。 九五：無妄之疾，勿藥有喜。象曰：無妄之藥，不可試也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>無妄，行有眚，無攸利。象曰：無妄之行，窮之災也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
